//! Font metrics for the layout solver. The advance widths ship as a
//! pre-generated static table ([`font_metrics`], sorted `(codepoint,
//! advance)` pairs per face, generated by `scripts/gen_font_table.py` from
//! the DejaVu fonts the table replaced) — `measure()` and `wrap()` return
//! bit-identical widths to the old embedded-TTF + ttf-parser path, at ~6
//! bytes per glyph instead of ~2.16 MB of embedded fonts. CJK glyph widths
//! are approximated (full-width em) until M2 ships subset CJK fonts.

use crate::font_metrics::{SANS_ADV, SANS_BOLD_ADV, SERIF_ADV, SERIF_BOLD_ADV};

fn table(serif: bool, bold: bool) -> &'static [(u32, u16)] {
    match (serif, bold) {
        (true, true) => SERIF_BOLD_ADV,
        (true, false) => SERIF_ADV,
        (false, true) => SANS_BOLD_ADV,
        (false, false) => SANS_ADV,
    }
}

fn upem(serif: bool, bold: bool) -> f64 {
    // All four bundled DejaVu faces are 2048 units per em.
    let _ = (serif, bold);
    crate::font_metrics::SANS_UPEM as f64
}

fn is_fullwidth(c: char) -> bool {
    let u = c as u32;
    (0x1100..=0x115F).contains(&u) // Hangul Jamo
        || (0x2E80..=0xA4CF).contains(&u) // CJK radicals..Yi
        || (0xAC00..=0xD7AF).contains(&u) // Hangul syllables
        || (0xF900..=0xFAFF).contains(&u)
        || (0xFF00..=0xFF60).contains(&u) // fullwidth forms
        || (0x20000..=0x3FFFD).contains(&u)
}

/// Advance of a single character in the table (font units), or None when
/// the face has no mapping for it.
fn advance_units(c: char, serif: bool, bold: bool) -> Option<u32> {
    let table = table(serif, bold);
    let cp = c as u32;
    table
        .binary_search_by(|probe| probe.0.cmp(&cp))
        .ok()
        .map(|idx| table[idx].1 as u32)
}

/// Width of a single character at `size` px. Unknown glyphs fall back to
/// 0.55em (a decent average for proportional Latin text).
fn char_width(c: char, size: f64, serif: bool, bold: bool) -> f64 {
    if is_fullwidth(c) {
        return size; // approximate CJK full-width until M2
    }
    match advance_units(c, serif, bold) {
        Some(adv) => {
            let upem = upem(serif, bold);
            if upem > 0.0 {
                adv as f64 / upem * size
            } else {
                size * 0.55
            }
        }
        None => size * 0.55,
    }
}

/// Measured width of a rendered string.
pub fn measure(text: &str, size: f64, serif: bool, bold: bool) -> f64 {
    text.chars().map(|c| char_width(c, size, serif, bold)).sum()
}

/// Greedy word-wrap into lines that fit `max_w`. CJK text breaks per character.
pub fn wrap(text: &str, max_w: f64, size: f64, serif: bool, bold: bool) -> Vec<String> {
    let mut lines = Vec::new();
    let mut cur = String::new();
    let mut cur_w = 0.0;

    let push = |lines: &mut Vec<String>, cur: &mut String, cur_w: &mut f64| {
        if !cur.is_empty() {
            lines.push(std::mem::take(cur));
            *cur_w = 0.0;
        }
    };

    for token in tokenize(text) {
        let piece_w = measure(&token.piece, size, serif, bold);
        let sep_w = if token.needs_space && !cur.is_empty() { measure(" ", size, serif, bold) } else { 0.0 };
        if cur_w + sep_w + piece_w > max_w && !cur.is_empty() {
            push(&mut lines, &mut cur, &mut cur_w);
        }
        if token.needs_space && !cur.is_empty() && cur_w > 0.0 {
            cur.push(' ');
            cur_w += sep_w;
        }
        if piece_w > max_w {
            // single token longer than the box: hard-break by char
            for c in token.piece.chars() {
                let cw = char_width(c, size, serif, bold);
                if cur_w + cw > max_w && !cur.is_empty() {
                    push(&mut lines, &mut cur, &mut cur_w);
                }
                cur.push(c);
                cur_w += cw;
            }
        } else {
            cur.push_str(&token.piece);
            cur_w += piece_w;
        }
    }
    if !cur.is_empty() {
        lines.push(cur);
    }
    if lines.is_empty() {
        lines.push(String::new());
    }
    lines
}

struct Token {
    piece: String,
    needs_space: bool,
}

/// Split into layout tokens: runs of non-CJK characters, or single CJK
/// characters (which wrap per character, no space between).
fn tokenize(text: &str) -> Vec<Token> {
    let mut out: Vec<Token> = Vec::new();
    let mut buf = String::new();
    // A pending space PRECEDES the next token (wrap's contract). The old
    // tokenizer set the flag on the token BEFORE the space instead, which
    // read as "a space follows me" to wrap — gluing the last two tokens of
    // every line together ("brown fox" -> "brownfox") and eating leading
    // spaces. Same flag, correct direction.
    let mut pending_space = false;
    for c in text.chars() {
        if is_fullwidth(c) {
            if !buf.is_empty() {
                out.push(Token {
                    piece: std::mem::take(&mut buf),
                    needs_space: pending_space,
                });
                pending_space = false;
            }
            out.push(Token { piece: c.to_string(), needs_space: false });
        } else if c == ' ' {
            if !buf.is_empty() {
                out.push(Token {
                    piece: std::mem::take(&mut buf),
                    needs_space: pending_space,
                });
            }
            pending_space = true;
        } else {
            buf.push(c);
        }
    }
    if !buf.is_empty() {
        out.push(Token { piece: buf, needs_space: pending_space });
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn measure_is_sane() {
        let w = measure("Hello world", 20.0, false, false);
        assert!(w > 60.0 && w < 160.0, "measured {w}");
        // bold should not be dramatically narrower
        assert!(measure("Hello world", 20.0, false, true) >= w * 0.9);
    }

    #[test]
    fn wrap_respects_width() {
        let size = 20.0;
        let lines = wrap("the quick brown fox jumps over the lazy dog repeatedly", 200.0, size, false, false);
        assert!(lines.len() > 1);
        for l in &lines {
            assert!(measure(l, size, false, false) <= 200.0 + 1.0);
        }
    }

    #[test]
    fn cjk_wraps_by_char() {
        // 11 full-width chars at 24px in a 120px box -> 5 per line -> 3 lines.
        let lines = wrap("宏大的产品发布计划讨论", 120.0, 24.0, false, false);
        assert!(lines.len() >= 3);
    }

    #[test]
    fn wrap_keeps_inter_word_spaces() {
        // Regression: the tokenizer used to glue the last two tokens of
        // every line ("brown fox" -> "brownfox") and drop leading spaces.
        let lines = wrap("the quick brown fox", 10000.0, 20.0, false, false);
        assert_eq!(lines, vec!["the quick brown fox".to_string()]);
        // A space that must break the line lands on the next line, intact.
        // (70px admits "alpha" alone but not "alpha beta" at size 20.)
        let lines = wrap("alpha beta", 70.0, 20.0, false, false);
        assert_eq!(lines, vec!["alpha".to_string(), "beta".to_string()]);
        // Two spaces between words collapse to one (wrap semantics).
        let lines = wrap("a  b", 10000.0, 20.0, false, false);
        assert_eq!(lines.len(), 1);
        assert!(lines[0].chars().filter(|c| *c == ' ').count() >= 1);
    }

    #[test]
    fn table_matches_the_fonts_contract() {
        // The generated tables really are the DejaVu advances: spot checks
        // against the values the fonts have carried since the beginning
        // (DejaVu Sans: space 651/2048 em, 'H' 1540/2048 em; DejaVu Serif
        // 'H' 1786/2048 em — the last cross-check the old parser ran).
        assert_eq!(advance_units(' ', false, false), Some(651));
        assert_eq!(advance_units('H', false, false), Some(1540));
        assert_eq!(advance_units('H', true, false), Some(1786));
        // A codepoint DejaVu does not map falls back to the em-average.
        assert_eq!(advance_units('\u{10FFFF}', false, false), None);
    }
}
